"]},"name":"Set Mail Body","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"1f6160a2-a666-45ca-8f72-21901d59e49e","scriptFormat":"text/x-javascript","script":{"content":["tw.local.msgBody = 
    '<html dir="rtl" lang="ar">' +
    '<head>' +
        '<meta charset="UTF-8">' +
        '<style>' +
            'body { font-family: Arial, sans-serif; direction: rtl; text-align: right; margin: 20px; }' +
            '.container { border: 1px solid #ccc; padding: 20px; max-width: 500px; background-color: #f9f9f9; }' +
            '.header { font-size: 18px; margin-bottom: 10px; font-weight: bold; }' +
            'ul { list-style-type: none; padding: 0; }' +
            'li { margin-bottom: 5px; }' +
            '.note { margin-top: 20px; font-size: 12px; color: #555; }' +
        '</style>' +
    '</head>' +
    '<body>' +
        '<div class="container">' +
            '<div class="header">السيد / السيدة</div>' +
            '<p>رجاء العلم بأنه تم إنشاء طلب ورقمه هو <strong>' + tw.local.odcRequest.requestNo + '</strong> للعميل <strong>' + tw.local.odcRequest.CustomerInfo.customerName + '</strong> وتفاصيل الطلب هي:</p>' +
            '<ul>' +
                '<li>رقم العميل: <strong>' + tw.local.odcRequest.cif + '</strong></li>' +
                '<li>نوع الطلب: <strong>' + tw.local.odcRequest.BasicDetails.requestNature + '</strong></li>' +
                '<li>رقم العقد: <strong>' + tw.local.odcRequest.BasicDetails.flexCubeContractNo + '</strong></li>' +
                '<li>المبلغ الذي تمت إضافته: <strong>' + tw.local.odcRequest.ContractLiquidation.liqAmount + '</strong></li>' +
                '<li>العملة: <strong>' + tw.local.odcRequest.ContractLiquidation.liqCurrency + '</strong></li>' +
                '<li>تاريخ الحق: <strong>' + tw.local.creditDate + '</strong></li>' +
                '<li>رقم الفاتورة: <strong>' + tw.local.odcRequest.BasicDetails.Invoice[0].invoiceNo + '</strong></li>' +
                '<li>رقم بوليصة الشحن: <strong>' + tw.local.odcRequest.BasicDetails.Bills[0].billOfLadingRef + '</strong></li>' +
            '</ul>' +
            '<p class="note">الرجاء عدم الرد على هذه الرسالة. هذا بريد إلكتروني تم إنشاؤه تلقائيًا.</p>' +
        '</div>' +
    '</body>' +
    '</html>';
