TWComponent.script:
// update date
var creditDate = addOneHourToDate(tw.local.odcRequest.ContractLiquidation.creditValueDate);
tw.local.creditDate = formatDateToYMD(creditDate);
var userName = tw.local.odcRequest.initiator;
if(!!userName){
	var atr = "Task Email Address";
	var userEmail = tw.system.org.findUserByName(userName).attributes[atr] || "";
	tw.local.mailTo += "," + userEmail;
}

//Set Mail Subject
tw.local.subject = "ODC Request No. "+tw.local.odcRequest.appInfo.instanceID
			+" for Customer "+tw.local.odcRequest.CustomerInfo.customerName
			+" is collected "
			+"طلب التحصيل المستندى تصدير رقم "+tw.local.odcRequest.appInfo.instanceID
			+ " للعميل "+tw.local.odcRequest.CustomerInfo.customerName
			+"تم تحصيله";

//Set latest contract number
if(!!tw.local.odcRequest.BasicDetails.flexCubeContractNo3)
	tw.local.contractNumber = tw.local.odcRequest.BasicDetails.flexCubeContractNo3;
else if(!!tw.local.odcRequest.BasicDetails.flexCubeContractNo2)
	tw.local.contractNumber = tw.local.odcRequest.BasicDetails.flexCubeContractNo2;
else
	tw.local.contractNumber = tw.local.odcRequest.BasicDetails.flexCubeContractNo;
	
	

// add function to add 1hour to the input date
function addOneHourToDate(date) {
	if (date == null) return null;
	var newDate = new Date(date);
	newDate.setHours(newDate.getHours() + 1);
	return newDate;
}

function formatDateToYMD(date) {
  var year = date.getFullYear();
  var month = ('0' + (date.getMonth() + 1)).slice(-2);
  var day = ('0' + date.getDate()).slice(-2);

  return day + '-' + month + '-' + year;
}

